-- 089_forecast_engine.sql
-- Roadmap F.34: immutable, explained Forecast Final Cost history.
CREATE TABLE IF NOT EXISTS public.project_cost_forecast_versions(
 id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>=0),label text NOT NULL CHECK(btrim(label)<>''AND char_length(label)<=160),
 currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),approved_budget numeric(24,2),awarded_contract_value numeric(24,2)NOT NULL CHECK(awarded_contract_value>=0),approved_variations numeric(24,2)NOT NULL CHECK(approved_variations>=0),pending_exposure numeric(24,2)NOT NULL CHECK(pending_exposure>=0),pending_exposure_included numeric(24,2)NOT NULL CHECK(pending_exposure_included>=0 AND pending_exposure_included<=pending_exposure),
 previous_forecast numeric(24,2)NOT NULL CHECK(previous_forecast>=0),positive_drivers numeric(24,2)NOT NULL CHECK(positive_drivers>=0),savings numeric(24,2)NOT NULL CHECK(savings>=0),forecast_final_cost numeric(24,2)NOT NULL CHECK(forecast_final_cost>=0),potential_final_cost numeric(24,2)NOT NULL CHECK(potential_final_cost>=0),note text NOT NULL CHECK(char_length(note)<=3000),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version_number)
);
CREATE TABLE IF NOT EXISTS public.project_cost_forecast_movements(
 forecast_version_id uuid NOT NULL REFERENCES public.project_cost_forecast_versions(id)ON DELETE RESTRICT,project_id bigint NOT NULL,work_group_id uuid NOT NULL,reason_code text NOT NULL CHECK(reason_code IN('APPROVED_VARIATION','EXPECTED_VARIATION','SCOPE_CHANGE','SAVING','VALUE_ENGINEERING','CURRENCY_EFFECT','OTHER')),direction text NOT NULL CHECK(direction IN('INCREASE','DECREASE')),amount numeric(24,2)NOT NULL CHECK(amount>0),note text NOT NULL CHECK(btrim(note)<>''AND char_length(note)<=1000),PRIMARY KEY(forecast_version_id,work_group_id,reason_code,direction,note),FOREIGN KEY(forecast_version_id)REFERENCES public.project_cost_forecast_versions(id)ON DELETE RESTRICT
);
CREATE OR REPLACE FUNCTION private.prevent_forecast_snapshot_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'FORECAST_SNAPSHOT_IMMUTABLE'USING ERRCODE='55000';END;$$;
DROP TRIGGER IF EXISTS forecast_versions_immutable ON public.project_cost_forecast_versions;CREATE TRIGGER forecast_versions_immutable BEFORE UPDATE OR DELETE ON public.project_cost_forecast_versions FOR EACH ROW EXECUTE FUNCTION private.prevent_forecast_snapshot_mutation();
DROP TRIGGER IF EXISTS forecast_movements_immutable ON public.project_cost_forecast_movements;CREATE TRIGGER forecast_movements_immutable BEFORE UPDATE OR DELETE ON public.project_cost_forecast_movements FOR EACH ROW EXECUTE FUNCTION private.prevent_forecast_snapshot_mutation();
ALTER TABLE public.project_cost_forecast_versions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.project_cost_forecast_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY forecast_versions_select ON public.project_cost_forecast_versions FOR SELECT TO authenticated USING(lower((SELECT role FROM public.profiles WHERE id=auth.uid()))IN('pm','admin')AND public.can_write_project(project_id));
CREATE POLICY forecast_movements_select ON public.project_cost_forecast_movements FOR SELECT TO authenticated USING(lower((SELECT role FROM public.profiles WHERE id=auth.uid()))IN('pm','admin')AND public.can_write_project(project_id));
REVOKE ALL ON TABLE public.project_cost_forecast_versions,public.project_cost_forecast_movements FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_cost_forecast_versions,public.project_cost_forecast_movements TO authenticated;

CREATE OR REPLACE FUNCTION public.get_project_cost_forecast(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$
DECLARE u uuid:=auth.uid();r text;BEGIN SELECT lower(role)INTO r FROM public.profiles WHERE id=u;IF u IS NULL OR r NOT IN('pm','admin')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'FORECAST_FORBIDDEN'USING ERRCODE='42501';END IF;
RETURN jsonb_build_object('projectId',p_project_id,'versions',COALESCE((SELECT jsonb_agg(jsonb_build_object('forecastVersionId',v.id,'versionNumber',v.version_number,'label',v.label,'currencyCode',v.currency_code,'approvedBudget',v.approved_budget,'awardedContractValue',v.awarded_contract_value,'approvedVariations',v.approved_variations,'pendingExposure',v.pending_exposure,'pendingExposureIncluded',v.pending_exposure_included,'previousForecast',v.previous_forecast,'positiveDrivers',v.positive_drivers,'savings',v.savings,'forecastFinalCost',v.forecast_final_cost,'potentialFinalCost',v.potential_final_cost,'note',v.note,'createdAt',v.created_at,'movements',COALESCE((SELECT jsonb_agg(jsonb_build_object('workGroupId',m.work_group_id,'workGroupCode',g.code,'workGroupLabel',g.label,'reasonCode',m.reason_code,'direction',m.direction,'amount',m.amount,'note',m.note)ORDER BY g.code,m.reason_code)FROM public.project_cost_forecast_movements m JOIN public.work_ontology_work_groups g ON g.id=m.work_group_id WHERE m.forecast_version_id=v.id),'[]'::jsonb))ORDER BY v.version_number DESC)FROM public.project_cost_forecast_versions v WHERE v.project_id=p_project_id),'[]'::jsonb));END;$$;

CREATE OR REPLACE FUNCTION public.create_project_cost_forecast(p_project_id bigint,p_forecast_version_id uuid,p_label text,p_pending_exposure_included numeric,p_movements jsonb,p_note text,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();r text;req public.write_command_requests%ROWTYPE;a public.project_tender_awards%ROWTYPE;prev public.project_cost_forecast_versions%ROWTYPE;cur text;approved numeric;pending numeric;budget numeric;inc numeric;dec numeric;num integer;forecast numeric;potential numeric;result jsonb;x jsonb;
BEGIN SELECT lower(role)INTO r FROM public.profiles WHERE id=u;IF u IS NULL OR r NOT IN('pm','admin')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'FORECAST_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_forecast_version_id IS NULL OR p_client_request_id IS NULL OR btrim(COALESCE(p_label,''))=''OR jsonb_typeof(COALESCE(p_movements,'[]'))<>'array'OR COALESCE(p_pending_exposure_included,0)<0 THEN RAISE EXCEPTION'INVALID_FORECAST_COMMAND'USING ERRCODE='22023';END IF;
INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'forecast.create',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT *INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='forecast.create'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;PERFORM pg_advisory_xact_lock(p_project_id);
SELECT *INTO a FROM public.project_tender_awards WHERE project_id=p_project_id ORDER BY awarded_at DESC LIMIT 1;IF a.id IS NULL THEN RAISE EXCEPTION'FORECAST_REQUIRES_AWARDED_CONTRACT'USING ERRCODE='55000';END IF;cur:=a.currency_code;IF EXISTS(SELECT 1 FROM public.project_variations WHERE project_id=p_project_id AND status IN('SUBMITTED','UNDER_REVIEW','REVISION_REQUIRED','APPROVED')AND currency_code<>cur)THEN RAISE EXCEPTION'FORECAST_CURRENCY_MISMATCH'USING ERRCODE='22023';END IF;
SELECT COALESCE(sum(approved_amount)FILTER(WHERE status='APPROVED'),0),COALESCE(sum(proposed_amount)FILTER(WHERE status IN('SUBMITTED','UNDER_REVIEW','REVISION_REQUIRED')),0)INTO approved,pending FROM public.project_variations WHERE project_id=p_project_id;IF p_pending_exposure_included>pending THEN RAISE EXCEPTION'FORECAST_INCLUDED_EXPOSURE_EXCEEDS_PENDING'USING ERRCODE='22023';END IF;SELECT total_amount INTO budget FROM public.approved_budget_baselines WHERE project_id=p_project_id AND currency_code=cur;
SELECT *INTO prev FROM public.project_cost_forecast_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;num:=COALESCE(prev.version_number+1,0);
FOR x IN SELECT value FROM jsonb_array_elements(p_movements)LOOP IF COALESCE((x->>'amount')::numeric,0)<=0 OR x->>'direction'NOT IN('INCREASE','DECREASE')OR x->>'reasonCode'NOT IN('APPROVED_VARIATION','EXPECTED_VARIATION','SCOPE_CHANGE','SAVING','VALUE_ENGINEERING','CURRENCY_EFFECT','OTHER')OR btrim(COALESCE(x->>'note',''))=''OR NOT EXISTS(SELECT 1 FROM public.project_execution_scope_items i JOIN public.project_execution_scope_versions s ON s.id=i.execution_scope_version_id WHERE s.project_id=p_project_id AND i.work_group_id=(x->>'workGroupId')::uuid)THEN RAISE EXCEPTION'INVALID_FORECAST_MOVEMENT'USING ERRCODE='22023';END IF;END LOOP;
SELECT COALESCE(sum((value->>'amount')::numeric)FILTER(WHERE value->>'direction'='INCREASE'),0),COALESCE(sum((value->>'amount')::numeric)FILTER(WHERE value->>'direction'='DECREASE'),0)INTO inc,dec FROM jsonb_array_elements(p_movements);forecast:=COALESCE(prev.forecast_final_cost,a.contract_value)+inc-dec;IF forecast<a.contract_value+approved THEN RAISE EXCEPTION'FORECAST_BELOW_COMMITTED_COST'USING ERRCODE='23514';END IF;potential:=forecast+pending-p_pending_exposure_included;
INSERT INTO public.project_cost_forecast_versions VALUES(p_forecast_version_id,p_project_id,num,btrim(p_label),cur,budget,a.contract_value,approved,pending,p_pending_exposure_included,COALESCE(prev.forecast_final_cost,a.contract_value),inc,dec,forecast,potential,btrim(COALESCE(p_note,'')),u,now());INSERT INTO public.project_cost_forecast_movements SELECT p_forecast_version_id,p_project_id,(value->>'workGroupId')::uuid,value->>'reasonCode',value->>'direction',(value->>'amount')::numeric,btrim(value->>'note')FROM jsonb_array_elements(p_movements);
result:=jsonb_build_object('forecastVersionId',p_forecast_version_id,'versionNumber',num,'forecastFinalCost',forecast,'potentialFinalCost',potential,'previousForecast',COALESCE(prev.forecast_final_cost,a.contract_value),'positiveDrivers',inc,'savings',dec,'currencyCode',cur);UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
REVOKE ALL ON FUNCTION private.prevent_forecast_snapshot_mutation()FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.get_project_cost_forecast(bigint),public.create_project_cost_forecast(bigint,uuid,text,numeric,jsonb,text,uuid)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.get_project_cost_forecast(bigint),public.create_project_cost_forecast(bigint,uuid,text,numeric,jsonb,text,uuid)TO authenticated;
